pkg() {
  # man-db with groff and gdbm (BUILD.md "System stage"). The formatter and
  # pager paths are given explicitly: configure would otherwise find the
  # build container's /usr/bin tools and bake those paths in. No setuid man binary;
  # the cache is regenerated by the mandb timer.
  pkg_autotools \
    --disable-static \
    --disable-setuid \
    --disable-cache-owner \
    --with-db=gdbm \
    --with-pager="${prefix}/bin/less" \
    --with-nroff="${prefix}/bin/nroff" \
    --with-troff="${prefix}/bin/troff" \
    --with-eqn="${prefix}/bin/eqn" \
    --with-neqn="${prefix}/bin/neqn" \
    --with-tbl="${prefix}/bin/tbl" \
    --with-preconv="${prefix}/bin/preconv" \
    --with-systemdtmpfilesdir="${prefix}/lib/tmpfiles.d" \
    --with-systemdsystemunitdir="${prefix}/lib/systemd/system"
}
